			/*
			 * "인터넷중독결과확인" 버튼(btnIntnetResult)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnIntnetResultClick(/* cpr.events.CMouseEvent */ e){
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btnIntnetResult = e.control;
			    
			    var totScore = ValueUtil.fixNumber(0);
			    var tot1Fctr = ValueUtil.fixNumber(0);
			    var tot3Fctr = ValueUtil.fixNumber(0);
			    var tot4Fctr = ValueUtil.fixNumber(0);
			    var isScore = false;  //결과 여부
			    
			    if (ValueUtil.isNull(app.lookup("cmbGradeSe").value)){
			          util.Msg.alert(app, "학년 구분을 선택해주세요.");
			          return false;
			    }

			    var dsList = app.lookup("dsList"); // 설문지문항정보
			    
			    for(var i = 0; i < dsList.getRowCount() - 16; i++) {
			        if(ValueUtil.isNull(dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE"))){
			          util.Msg.alert(app, "인터넷중독 진단 " + (i+1) + "번 문항을 입력해주세요.");
			          app.lookup("rdb" + (i).toString()).focus();
			          return false;
			        }

			        totScore += ValueUtil.fixNumber(dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE"));
			    }

			    //1요인 : 1, 5, 9, 12, 15번  합계
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(0, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(4, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(8, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(11, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(14, "QESITM_SINGL_RSPNS_VALUE"));
			    
			    //3요인 : 3, 7, 10, 13번  합계
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(2, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(6, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(9, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(12, "QESITM_SINGL_RSPNS_VALUE"));

			    //4요인 : 4, 8, 11, 14번  합계
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(3, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(7, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(10, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(14, "QESITM_SINGL_RSPNS_VALUE"));
			    
			    var optIntnetTot = app.lookup("optIntnetTot");
			    var optIntnet1FctrScore = app.lookup("optIntnet1FctrScore");
			    var optIntnet3FctrScore = app.lookup("optIntnet3FctrScore");
			    var optIntnet4FctrScore = app.lookup("optIntnet4FctrScore");
			    var cmbIntnetResult = app.lookup("cmbIntnetResult");
			    var cmbGradeSe = app.lookup("cmbGradeSe");
			    
			    optIntnetTot.value = totScore;
			    optIntnet1FctrScore.value = tot1Fctr;
			    optIntnet3FctrScore.value = tot3Fctr;
			    optIntnet4FctrScore.value = tot4Fctr;
			    
			    if (cmbGradeSe == "1") {  //초등
			        //고위험 사용자군
			        if (!isScore && totScore >= 42 ) {
			            cmbIntnetResult.value = "1";
			            isScore = true;
			        }
			    
			        if (!isScore && tot1Fctr >= 14 &&  tot3Fctr >= 13 && tot4Fctr >= 13) {
			            cmbIntnetResult.value = "1";
			            isScore = true;
			        }
			        
			        //잠재적 위험 사용자군
			        if (!isScore && totScore >= 39 &&  totScore <= 41) {
			            cmbIntnetResult.value = "2";
			            isScore = true;
			        }
			        
			        if (!isScore && tot1Fctr >= 13 || tot3Fctr >= 12 || tot4Fctr >= 12) {
			            cmbIntnetResult.value = "2";
			            isScore = true;
			        }
			        
			        //일반 사용자군
			        if (totScore <= 38 && tot1Fctr <= 12 &&  tot3Fctr <= 11 && tot4Fctr <= 11) {
			            cmbIntnetResult.value = "3";
			        }
			        
			    } else {
			        //고위험 사용자군
			        if (!isScore && totScore >= 44 ) {
			            cmbIntnetResult.value = "1";
			            isScore = true;
			        }
			    
			        if (!isScore && tot1Fctr >= 15 &&  tot3Fctr >= 13 && tot4Fctr >= 14) {
			            cmbIntnetResult.value = "1";
			            isScore = true;
			        }
			        
			        //잠재적 위험 사용자군
			        if (!isScore && totScore >= 41 &&  totScore <= 43) {
			            cmbIntnetResult.value = "2";
			            isScore = true;
			        }
			        
			        if (!isScore && tot1Fctr >= 14 || tot3Fctr >= 12 && tot4Fctr >= 12) {
			            cmbIntnetResult.value = "2";
			            isScore = true;
			        }
			        
			        //일반 사용자군
			        if (totScore <= 40 && tot1Fctr <= 13 &&  tot3Fctr <= 11 && tot4Fctr <= 11) {
			            cmbIntnetResult.value = "3";
			        }
			        
			    }
			        
			}


