			    if (ValueUtil.isNull(app.lookup("cmbGradeSe").value)){
			          util.Msg.alert(app, "학년 구분을 선택해주세요.");
			          app.lookup("cmbGradeSe").focus();
			          return false;
			    }

			    var dsList = app.lookup("dsList"); // 설문지문항정보
			    
			    for (var i = 15; i < dsList.getRowCount() - 1; i++) {
			        if (ValueUtil.isNull(dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE"))){
			          util.Msg.alert(app, "스마트폰중독 진단 " + (i+1) + "번 문항을 입력해주세요.");
			          app.lookup("rdb" + (i).toString()).focus();
			          return false;
			        }

			        totScore += ValueUtil.fixNumber(dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE"));
			    }

			    //1요인 : 1, 5, 9, 12, 13번  합계
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(0+15, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(4+15, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(8+15, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(11+15, "QESITM_SINGL_RSPNS_VALUE"));  
			    tot1Fctr += ValueUtil.fixNumber(dsList.getValue(12+15, "QESITM_SINGL_RSPNS_VALUE"));
			    
			    //3요인 : 3, 7, 10, 14번  합계
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(2+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(6+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(9+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot3Fctr += ValueUtil.fixNumber(dsList.getValue(13+15, "QESITM_SINGL_RSPNS_VALUE"));

			    //4요인 : 4, 8, 11, 15번  합계
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(3+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(7+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(10+15, "QESITM_SINGL_RSPNS_VALUE"));
			    tot4Fctr += ValueUtil.fixNumber(dsList.getValue(14+15, "QESITM_SINGL_RSPNS_VALUE"));
			    
			    var optSmrtpTot = app.lookup("optSmrtpTot");
			    var optSmrtp1FctrScore = app.lookup("optSmrtp1FctrScore");
			    var optSmrtp3FctrScore = app.lookup("optSmrtp3FctrScore");
			    var optSmrtp4FctrScore = app.lookup("optSmrtp4FctrScore");
			    var cmbSmrtpResult = app.lookup("cmbSmrtpResult");
			    
			    optSmrtpTot.value = totScore;
			    optSmrtp1FctrScore.value = tot1Fctr;
			    optSmrtp3FctrScore.value = tot3Fctr;
			    optSmrtp4FctrScore.value = tot4Fctr;
			    
			    //고위험 사용자군
			    if (!isScore && totScore >= 45 ) {
			        cmbSmrtpResult.value = "1";
			        isScore = true;
			    }

			    if (!isScore && tot1Fctr >= 16 &&  tot3Fctr >= 13 && tot4Fctr >= 14) {
			        cmbSmrtpResult.value = "1";
			        isScore = true;
			    }
			    
			    //잠재적 위험 사용자군
